  input = update_context(input, schema)

  {_node, _acc} =
    Blueprint.prewalk(input.operations, nil, fn node, acc ->
      {handle_node(node, schema, input.adapter), acc}
    end)

  {:ok, input}
end

def upto(pipeline, phase) do
  Enum.reduce_while(pipeline, [], fn item, acc ->
    if match_phase?(phase, item) do
      {:halt, [item | acc]}
    else
      {:cont, [item | acc]}
    end
  end)
  |> Enum.reverse()
end

